$('projectList').onclick=async e=>{const button=e.target.closest('button');if(!button)return;const id=button.dataset.open||button.dataset.remove,d=docs.find(d=>d.id===id);if(!d)return;if(button.dataset.open)open(d);else if(confirm(`Projekt «${d.name}» auf diesem Gerät löschen?`)){try{await database('delete',id);docs=docs.filter(d=>d.id!==id);home();}catch(e){toast(e.message)}}};
$('backHome').onclick=async()=>{await flush();doc=null;wire=null;$('editor').hidden=true;$('cadHome').hidden=false;home();};
$('backupProject').onclick=()=>download(new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}),`${doc.order||doc.name} - CAD.json`);
$('importProject').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>20*1024*1024)throw Error('Projektdatei zu gross (max. 20 MB).');const d=validateProject(JSON.parse(await f.text()));d.id=uid();d.name+=' (Import)';await database('save',d);docs.push(d);open(d);}catch(e){toast(e.message)}finally{$('importProject').value=''}};
$('addPage').onclick=()=>showForm('Seite hinzufügen',[{key:'title',label:'Seitentitel (leer = automatisch)',value:''},{key:'type',label:'Seitentyp',value:'schema',options:[['schema','Elektroschema'],['dispo','Disposition'],['cover','Deckblatt'],['index','Inhaltsverzeichnis']]},{key:'before',label:'Einfügen vor',value:'',options:[['','Am Ende'],...doc.pages.map(p=>[p.id,`Blatt ${p.number} · ${p.title}`])]},{key:'inherit',label:'Sammelschienen übernehmen von',value:current().type==='schema'?current().id:'',options:[['','Keine Übernahme'],...doc.pages.filter(p=>p.type==='schema').map(p=>[p.id,`Blatt ${p.number} · ${p.title}`])]}],data=>{if(doc.pages.length>=200)throw Error('Maximal 200 Seiten pro Projekt.');change(()=>{const p=page(data.type,Math.max(...doc.pages.map(p=>p.number))+1);p.title=data.title.trim()||p.title;const index=doc.pages.findIndex(q=>q.id===data.before);doc.pages.splice(index<0?doc.pages.length:index,0,p);if(data.type==='schema'&&data.inherit)inheritBus(doc,doc.pages.find(q=>q.id===data.inherit),p);pageId=p.id;selected=null;multi=[];wire=null;});});
$('pageCaption').onclick=$('pageList').onclick=e=>{const b=e.target.closest('[data-page]');if(b){pageId=b.dataset.page;hoverPoint=null;selected=null;multi=[];wire=null;render();}};
$('copyPage').onclick=()=>{if(doc.pages.length>=200)return toast('Maximal 200 Seiten pro Projekt.');change(()=>{const q=duplicatePage(doc,current());doc.pages.splice(doc.pages.indexOf(current())+1,0,q);pageId=q.id;selected=null;multi=[];wire=null;});};
$('deletePage').onclick=()=>{if(doc.pages.length>1&&confirm('Diese Seite mit allen Elementen entfernen?'))change(()=>{doc.pages=doc.pages.filter(p=>p.id!==pageId);pageId=doc.pages[0].id;selected=null;multi=[];wire=null;});};
function movePage(delta){const i=doc.pages.indexOf(current()),j=i+delta;if(j<0||j>=doc.pages.length)return;change(()=>[doc.pages[i],doc.pages[j]]=[doc.pages[j],doc.pages[i]]);}
$('movePageUp').onclick=()=>movePage(-1);$('movePageDown').onclick=()=>movePage(1);
function symbolList(){
 const q=$('symbolSearch').value,previous=$('symbolGroup').value;
 const originals=templateCatalog?.items||[];
 const groups=[...new Set([...Object.values(symbols).filter(s=>s.group!=='Vorlagen').map(s=>s.group),...originals.map(t=>libraryFacets(t).group)])].sort((a,b)=>a.localeCompare(b,'de'));
 $('symbolGroup').innerHTML='<option value="">Alle Gruppen</option>'+groups.map(g=>`<option value="${esc(g)}">${esc(libraryName(g))}</option>`).join('');$('symbolGroup').value=groups.includes(previous)?previous:'';
 const group=$('symbolGroup').value;
 const basic=filterLibrary(Object.entries(symbols).filter(([k])=>k!=='template').map(([kind,s])=>({...s,id:kind,kind,source:'Grundsymbol'})),{query:q,group});
 const imported=filterLibrary(originals,{query:q,group});
 const items=[...basic,...imported],shown=items.slice(0,symbolLimit);
 $('symbolStatus').textContent=`${items.length} Einträge · ${Math.min(items.length,symbolLimit)} angezeigt${templateCatalog?'':' · Originalbibliothek wird geladen …'}`;
 $('symbolList').innerHTML=shown.map(t=>t.kind?`<button class="symbol-card" data-symbol="${t.kind}"><span class="symbol-picture"><svg viewBox="-10 -5 ${t.w+20} ${t.h+10}" fill="none" stroke="currentColor" stroke-width="2">${glyph(t.kind)||'<rect x="2" y="2" width="32" height="40"/>'}</svg></span><strong>${esc(t.name)}</strong><small>Grundsymbol · ${esc(t.group)}</small></button>`:`<button class="symbol-card" data-template="${esc(t.id)}"><span class="symbol-picture"><img src="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27/%3E" data-preview-id="${esc(t.id)}" loading="lazy" alt="${esc(t.name)}"></span><strong>${esc(libraryName(t.name))}</strong><small>${esc(t.category)} · ${esc(libraryFacets(t).group)}</small></button>`).join('')||'<p class="hint">Keine Treffer. Suchbegriff oder Gruppe ändern.</p>';
 $('moreSymbols').hidden=items.length<=symbolLimit;
}


async function loadTemplates(){if(templateCatalog){renderTemplates();symbolList();return;}$('templateStatus').textContent='Vorlagen werden geladen …';try{const r=await fetch('cad/templates/catalog.json?v=20261118-5');if(!r.ok)throw Error('Vorlagenbibliothek nicht erreichbar');templateCatalog=await r.json();renderTemplates();symbolList();}catch(e){$('templateStatus').textContent=e.message;$('symbolStatus').textContent=e.message;}}
function renderTemplates(){
 const category=$('templateCategory').value,previous=$('templateGroup').value;
 for(const [id,key,label] of [['templateDomain','domain','Alle Fachbereiche'],['templateManufacturer','manufacturer','Alle Hersteller']]){const old=$(id).value,values=[...new Set(templateCatalog.items.filter(t=>!category||t.category===category).map(t=>libraryFacets(t)[key]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'de'));$(id).innerHTML=`<option value="">${label}</option>`+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');$(id).value=values.includes(old)?old:'';}
 const groups=[...new Set(filterLibrary(templateCatalog.items,{category,domain:$('templateDomain').value,manufacturer:$('templateManufacturer').value}).map(t=>libraryFacets(t).group))].sort((a,b)=>libraryName(a).localeCompare(libraryName(b),'de'));
 $('templateGroup').innerHTML='<option value="">Alle Gruppen</option>'+groups.map(g=>`<option value="${esc(g)}">${esc(libraryName(g))}</option>`).join('');$('templateGroup').value=groups.includes(previous)?previous:'';
 const items=filterLibrary(templateCatalog.items,{query:$('templateSearch').value,category,domain:$('templateDomain').value,manufacturer:$('templateManufacturer').value,group:$('templateGroup').value,scope:libraryScope,...librarySettings});
 $('templateStatus').textContent=`${items.length} Vorlagen · ${Math.min(items.length,templateLimit)} angezeigt`;
 $('templateList').innerHTML=items.slice(0,templateLimit).map(t=>`<div class="template-tile"><button class="favorite-toggle" data-favorite="${esc(t.id)}" aria-label="${esc(t.name)} als Favorit" aria-pressed="${librarySettings.favorites.includes(t.id)}" title="Favorit merken">${librarySettings.favorites.includes(t.id)?'★':'☆'}</button><button class="template-card ${activeTemplate?.id===t.id?'active':''}" data-template="${esc(t.id)}" title="${esc(t.name)}"><span class="template-picture"><img src="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27/%3E" data-preview-id="${esc(t.id)}" loading="lazy" alt="Vorschau ${esc(t.name)}"></span><strong>${esc(libraryName(t.name))}</strong><small>${esc(libraryFacets(t).group)}${libraryFacets(t).manufacturer?' · '+esc(libraryFacets(t).manufacturer):''} · ${t.width} × ${t.height} mm</small><span class="template-badge">${t.supplyPorts?'↳ Sammelschienen · ':''}${t.liveLabels?'Autom. Kennzeichen':esc(t.category)}</span></button></div>`).join('')||`<div class="library-empty"><strong>${libraryScope==='favorites'?'Noch keine passenden Favoriten':libraryScope==='recent'?'Noch keine passenden Vorlagen verwendet':'Keine passende Vorlage'}</strong><p>${libraryScope==='favorites'?'Mit ☆ auf einer Vorlage legst du sie hier ab.':'Suche oder Filter ändern. Unter «Alle» findest du die gesamte Bibliothek.'}</p><button id="resetLibrary">Alle Vorlagen anzeigen</button></div>`;
 $('moreTemplates').hidden=items.length<=templateLimit;
 $('resetLibrary')?.addEventListener('click',()=>{$('templateSearch').value='';$('templateCategory').value='';$('templateGroup').value='';$('templateDomain').value='';$('templateManufacturer').value='';setLibraryScope('all');});
}
function setLibraryScope(scope){libraryScope=scope;templateLimit=40;document.querySelectorAll('[data-scope]').forEach(b=>{b.classList.toggle('active',b.dataset.scope===scope);b.setAttribute('aria-pressed',b.dataset.scope===scope);});if(templateCatalog)renderTemplates();}
document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>setLibraryScope(b.dataset.scope));
$('templateSearch').oninput=$('templateCategory').onchange=$('templateDomain').onchange=$('templateManufacturer').onchange=$('templateGroup').onchange=()=>{templateLimit=40;if(templateCatalog)renderTemplates();};$('moreTemplates').onclick=()=>{templateLimit+=40;renderTemplates();};
$('templateList').onclick=async event=>{const favorite=event.target.closest('[data-favorite]');if(favorite){const id=favorite.dataset.favorite;librarySettings.favorites=librarySettings.favorites.includes(id)?librarySettings.favorites.filter(x=>x!==id):[...librarySettings.favorites,id];saveLibrarySettings();renderTemplates();return;}const b=event.target.closest('[data-template]');if(!b)return;const request=++templateRequest;b.disabled=true;try{const r=await fetch(`cad/templates/${b.dataset.template}.json?v=20261118-5`);if(!r.ok)throw Error('Vorlage nicht erreichbar');const template=validateTemplate(await r.json());await loadDetails();if(templateDetails[template.id])template.details=templateDetails[template.id];if(request!==templateRequest)return;activeTemplate=template;setTool('template');$('templateSelected').textContent=template.name;renderTemplates();$('templatePreview').innerHTML=templateMarkup(template,Math.min(170/template.width,120/template.height)*template.width,Math.min(170/template.width,120/template.height)*template.height);toast('Vorlage gewählt – auf dem Blatt platzieren. R dreht die Vorschau.');document.querySelector('.drawing-layout').classList.remove('show-left');}catch(e){toast(e.message)}finally{b.disabled=false;}};

$('symbolSearch').oninput=$('symbolGroup').onchange=()=>{symbolLimit=60;symbolList();};$('moreSymbols').onclick=()=>{symbolLimit+=60;symbolList();};$('symbolList').onclick=e=>{if(e.target.closest('[data-template]')){$('templateList').onclick(e);return;}const b=e.target.closest('[data-symbol]');if(b){if(current().type==='dispo'&&['cabinet','duct','rail'].includes(b.dataset.symbol))insertDispoPart(b.dataset.symbol);else setTool(b.dataset.symbol);document.querySelector('.drawing-layout').classList.remove('show-left');}};
document.querySelectorAll('[data-left]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-left]').forEach(x=>x.classList.toggle('active',x===b));$('pagesPanel').hidden=b.dataset.left!=='pages';$('symbolsPanel').hidden=b.dataset.left!=='symbols';$('templatesPanel').hidden=b.dataset.left!=='templates';if(['templates','symbols'].includes(b.dataset.left))loadTemplates();});
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
$('toggleLeft').onclick=()=>document.querySelector('.drawing-layout').classList.toggle('show-left');$('toggleRight').onclick=()=>document.querySelector('.drawing-layout').classList.toggle('show-right');
$('fit').onclick=fit;$('zoomIn').onclick=()=>zoomBy(1.2);$('zoomOut').onclick=()=>zoomBy(1/1.2);$('undo').onclick=()=>history('undo');$('redo').onclick=()=>history('redo');
function deleteSelected(){if(multi.length){change(()=>{deleteSelection(current(),multi,uid);multi=[];selected=null;});return;}if(!selected)return;change(()=>{const p=current();removeElement(p,selected);removeWire(p,selected);selected=null;multi=[];});}
function duplicateSelected(){if(multi.length>1||multi.some(s=>['line','text'].includes(s.kind)))return toast('Zum Duplizieren ein ganzes Element auswählen.');const p=current(),e=p.elements.find(e=>e.id===selected),w=p.wires.find(w=>w.id===selected);if(!e&&!w)return;change(()=>{if(e){const c=clone(e),fresh=createElement(p,e.kind,e.x+20,e.y+20);Object.assign(c,{id:fresh.id,x:fresh.x,y:fresh.y,tag:fresh.tag});for(const f of Object.values(c.functions||{}))if(f.role==='contact')delete f.owner;if(c.terminalStrip){const used=doc.pages.flatMap(q=>q.elements).filter(q=>q.terminalStrip?.name===c.terminalStrip.name).map(q=>q.terminalStrip.number);c.terminalStrip.number=Math.max(0,...used)+1;if(c.terminalStrip.number>9999)throw Error('Keine freie Klemmennummer bis 9999.');c.terminalStrip.first=false;}p.elements.push(c);selected=c.id;}else{const c=clone(w);c.id=uid();c.points=wirePoints(p,w).map(pt=>({x:pt.x+20,y:pt.y+20}));c.from=c.to=null;p.wires.push(c);selected=c.id;}});}
function rotate(){if(twoPointPart())return;if(multi.length>1||multi.some(s=>['line','text'].includes(s.kind)))return toast('Zum Drehen ein ganzes Element auswählen.');if(symbols[tool]){placementRotation=(placementRotation+90)%360;drawPlacement();return;}const e=current().elements.find(e=>e.id===selected);if(e)change(()=>e.rotation=(e.rotation+90)%360);}
$('deleteElement').onclick=deleteSelected;$('duplicateElement').onclick=duplicateSelected;$('rotate').onclick=rotate;
function point(event,grid=true){const rect=$('paper').getBoundingClientRect();return {x:snap((event.clientX-rect.left)/zoom,grid&&$('snap').checked),y:snap((event.clientY-rect.top)/zoom,grid&&$('snap').checked)};}
function measurePoint(event){const pt=point(event,false);return $('objectSnap').checked?nearestDrawingPoint(current(),pt,10/zoom):point(event);}
function nearest(pt,excludeWire=null){let best=null,dist=10/zoom;const page=current();const consider=(q,ref)=>{const n=Math.hypot(q.x-pt.x,q.y-pt.y);if(n<dist&&(!excludeWire||canLinkWire(page,excludeWire,ref))){dist=n;best={x:q.x,y:q.y,ref};}};
 for(const e of page.elements){for(const port of ports(e,page))consider(port,{element:e.id,index:port.index});if(e.template){const [w,h]=size(e,page);for(const line of templateLines(e.template)){const pts=linePoints(e,page,line);[line.a,line.b].forEach((q,i)=>consider(pts[i],{element:e.id,local:{x:q.x/e.template.viewWidth,y:q.y/e.template.viewHeight}}));}}}
 for(const q of page.connectionPoints||[])consider(q,{connection:q.id});
 for(const w of page.wires){if(w.id===excludeWire)continue;const pts=wirePoints(page,w);consider(pts[0],{wire:w.id,index:0});consider(pts.at(-1),{wire:w.id,index:1});}return best;
}
function wireRoutes(hover){const points=[...(wire?.points||[]),...(hover?[hover]:[])];return parallelRoutes(points,Number($('wireCount').value),Number($('wireSpacing').value)*MM,verticalWire);}
function wirePreview(hover){const svg=$('paper').querySelector('svg');svg?.querySelector('#wirePreview')?.remove();if(!svg||!wire)return;try{const routes=wireRoutes(hover);svg.insertAdjacentHTML('beforeend',`<g id="wirePreview" fill="none" stroke="#2463eb" stroke-width="1.5" stroke-dasharray="5 3" pointer-events="none">${routes.map(pts=>`<polyline points="${pts.map(p=>p.x+','+p.y).join(' ')}"/>`).join('')}</g>`);$('drawingHint').textContent='Zwischenpunkte klicken · Enter abschliessen · Tab Knick wechseln';}catch(error){$('drawingHint').textContent=error.message;}}
function finishWire(){if(!wire||wire.points.length<2)return toast('Mindestens zwei Punkte für eine Verbindung setzen.');try{const routes=wireRoutes();if(current().elements.length+current().wires.length+routes.length>5000)throw Error('Maximal 5000 Elemente pro Seite.');if(routes.some(r=>r.some(pt=>pt.x<DRAW.left||pt.x>DRAW.right||pt.y<DRAW.top||pt.y>DRAW.bottom)))throw Error('Alle Leitungen müssen innerhalb des Zeichenbereichs liegen.');if(routes.some(r=>r.length>200))throw Error('Maximal 200 Punkte pro Verbindung.');const ws=routes.map((points,i)=>({id:i?uid():wire.id,points,from:i?nearestExact(points[0]):wire.from,to:i?nearestExact(points.at(-1)):wire.to,dashed:false,label:''}));change(()=>{current().wires.push(...ws);wire=null;selected=ws[0].id;});}catch(error){toast(error.message);}}
function nearestExact(pt){const hit=nearest(pt);return hit&&Math.hypot(hit.x-pt.x,hit.y-pt.y)<.05?hit.ref:null;}

$('finishWire').onclick=finishWire;$('cancelWire').onclick=()=>{wire=null;drawPaper();};
$('paper').onpointerdown=event=>{if(event.button!==0||tool==='pan')return;const p=current(),pt=point(event);if(twoPointPart()){placeLinearPoint(event);return;}if(tool==='dimension'){event.preventDefault();const q=measurePoint(event);if(q.x<DRAW.left||q.x>DRAW.right||q.y<DRAW.top||q.y>DRAW.bottom)return;if(measurePoints.length<2){measurePoints.push(q);drawPlacement();drawingOptions();}else{const e=makeDimension(p,...measurePoints,q,$('measureAxis').value);if(!e)return toast('Zwei unterschiedliche Messpunkte wählen.');if(p.elements.length+p.wires.length>=5000)return toast('Maximal 5000 Elemente pro Seite.');change(()=>{p.elements.push(e);selected=e.id;measurePoints=[];});}return;}if(pt.x<25||pt.x>1175||pt.y<35||pt.y>DRAW.bottom)return;
 const tariff=event.target.closest('[data-tariff-target]');if(tool==='select'&&tariff){event.preventDefault();const r=JSON.parse(tariff.dataset.tariffTarget);navigateTariff(r.page,r.element);return;}
 const autoPort=event.target.closest('[data-auto-port]');if(tool==='select'&&autoPort){const [id,index]=autoPort.dataset.autoPort.split(':');selected=id;drag={autoPort:Number(index),id,before:clone(doc),moved:false};textClicks.reset();event.preventDefault();$('paper').setPointerCapture(event.pointerId);return;}
 const connection=event.target.closest('[data-connection]');if(tool==='select'&&connection){textClicks.reset();event.preventDefault();showConnection(JSON.parse(connection.dataset.connection),event.shiftKey||event.ctrlKey||event.metaKey);return;}
 if(tool==='select'&&!event.target.closest('[data-wire-handle]')){connectionSelection=[];startSelection(event,pt);return;}
 const handle=event.target.closest('[data-wire-handle]');if(tool==='select'&&handle){const [id,index]=handle.dataset.wireHandle.split(':');const w=p.wires.find(w=>w.id===id);selected=id;drag={wire:id,handle:Number(index),start:pt,before:clone(doc),moved:false};$('paper').setPointerCapture(event.pointerId);return;}
 if(tool==='wire'){if(p.elements.length+p.wires.length>=5000)return toast('Maximal 5000 Elemente pro Seite.');event.preventDefault();if(wire?.points.length>=199)return toast('Verbindung abschliessen: maximal 200 Punkte.');const port=nearest(pt),pos=port?{x:port.x,y:port.y}:pt;if(!wire)wire={id:uid(),points:[pos],from:port?port.ref:null,to:null,dashed:false,label:''};else{if(Math.hypot(pos.x-wire.points.at(-1).x,pos.y-wire.points.at(-1).y)<.1)return;wire.points.push(pos);if(port){wire.to=port.ref;finishWire();return;}}drawPaper();return;}
 if(tool!=='select'){
  try{const g=drawingPlacement(pt);if(!g)return toast('Bauteil passt hier nicht auf das Blatt. Einfügepunkt oder Position ändern.');if(p.elements.length+p.wires.length+g.elements.length+g.wires.length>5000)throw Error('Maximal 5000 Elemente pro Seite.');change(()=>{p.elements.push(...clone(g.elements));p.wires.push(...g.wires);const e=g.elements[0];if(e.template){librarySettings.recent=rememberTemplate(librarySettings.recent,e.template.id);saveLibrarySettings();if(templateCatalog)renderTemplates();}selected=e.id;hoverPoint=null;if(pendingAssembly){pendingAssembly=null;tool='select';}});}catch(error){toast(error.message);}return;
 }

 const target=event.target.closest('[data-element]'),wireTarget=event.target.closest('[data-wire]');selected=target?.dataset.element||wireTarget?.dataset.wire||null;if(wireTarget&&!target){const w=p.wires.find(w=>w.id===selected);drag={wire:w.id,start:pt,points:wirePoints(p,w).map(q=>({x:q.x,y:q.y})),before:clone(doc),moved:false};$('paper').setPointerCapture(event.pointerId);}if(target){const e=p.elements.find(e=>e.id===selected);drag={id:e.id,start:pt,x:e.x,y:e.y,before:clone(doc),moved:false};$('paper').setPointerCapture(event.pointerId);}render();};
$('paper').onpointermove=event=>{if(navigation.isPanning()||tool==='pan')return;const pt=point(event);hoverPoint=twoPointPart()?linearPointer(event):tool==='dimension'?measurePoint(event):pt;$('cursorPosition').textContent=`Pfad ${pathAt(pt.x)} · X ${Math.round(pt.x)} · Y ${Math.round(pt.y)}`;if(drag?.autoPort!==undefined){const phase=Object.keys(BUS).find(k=>Math.abs(BUS[k]-pt.y)<7);if(phase){const e=current().elements.find(e=>e.id===drag.id);e.autoPhases??={};e.autoPhases[drag.autoPort]=phase;drag.moved=true;drawPaper();}return;}if(drag?.marquee){drag.end=pt;drawPaper();return;}if(drag?.multiple){const before=drag.before.pages.find(p=>p.id===pageId),desired=$('objectSnap').checked&&!event.altKey?snapMove(current(),before,multi,pt.x-drag.start.x,pt.y-drag.start.y,8/zoom):{dx:pt.x-drag.start.x,dy:pt.y-drag.start.y};const dx=desired.dx-(drag.applied?.dx||0),dy=desired.dy-(drag.applied?.dy||0);snapGuides=desired.guides||null;if(dx||dy){if(!drag.moved){try{multi=materializeLines(current(),multi,uid);}catch(error){endDrag(true);toast(error.message);return;}}try{moveSelection(current(),multi,dx,dy);}catch(error){endDrag(true);toast(error.message);return;}drag.last=pt;drag.applied=desired;drag.moved=true;syncSelection();drawPaper();}return;}if(drag?.wire){const w=current().wires.find(w=>w.id===drag.wire);if(drag.handle!==undefined){const i=drag.handle===0?0:w.points.length-1,ref=drag.handle===0?'from':'to',hit=nearest(pt,w.id);w.points[i]=hit?{x:hit.x,y:hit.y}:{x:pt.x,y:pt.y};w[ref]=hit?.ref||null;}else{w.points=drag.points.map(q=>({x:q.x+pt.x-drag.start.x,y:q.y+pt.y-drag.start.y}));w.from=w.to=null;}drag.moved=true;drawPaper();}else if(drag){const e=current().elements.find(e=>e.id===drag.id);e.x=Math.max(30,Math.min(1140,drag.x+pt.x-drag.start.x));e.y=Math.max(40,Math.min(DRAW.bottom,drag.y+pt.y-drag.start.y));if(e.kind==='template'){const [w,h]=size(e,current()),b=bounds(e,w,h);e.x+=Math.max(0,DRAW.left-b.left)-Math.max(0,b.right-DRAW.right);e.y+=Math.max(0,DRAW.top-b.top)-Math.max(0,b.bottom-DRAW.bottom);}if(e.x!==drag.x||e.y!==drag.y)drag.moved=true;drawPaper();}else if(wire)wirePreview(nearest(pt)||pt);else drawPlacement();};
